import React, { useState } from 'react';
import TaskList from './TaskList';
import Timer from './Timer';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS } from 'chart.js/auto';

function App() {
  const [tasks, setTasks] = useState([]);
  const [task, setTask] = useState("");
  const [selectedQuadrant, setSelectedQuadrant] = useState(1);

  const addTask = () => {
    const newTask = { id: Date.now(), text: task, quadrant: selectedQuadrant, timer: 0, completed: false };
    setTasks([...tasks, newTask]);
    setTask("");
  };

  const deleteTask = (taskId) => {
    setTasks(tasks.filter(t => t.id !== taskId));
  };

  const toggleTaskCompletion = (taskId) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, completed: !t.completed } : t));
  };

  const startTimer = (taskId) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, timer: Date.now() } : t));
  };

  const stopTimer = (taskId) => {
    const taskToUpdate = tasks.find(t => t.id === taskId);
    if (taskToUpdate) {
      const duration = (Date.now() - taskToUpdate.timer) / 1000; // seconds
      setTasks(tasks.map(t => t.id === taskId ? { ...t, timer: duration } : t));
    }
  };

  const chartData = {
    labels: tasks.map(t => t.text),
    datasets: [
      {
        label: 'Task Duration (seconds)',
        data: tasks.map(t => t.timer),
        borderColor: 'rgba(75, 192, 192, 1)',
        backgroundColor: 'rgba(75, 192, 192, 0.2)',
        borderWidth: 1,
      },
    ],
  };

  return (
    <div className="App">
      <h1>Eisenhower Matrix</h1>
      <input
        type="text"
        value={task}
        onChange={(e) => setTask(e.target.value)}
        placeholder="Enter Task"
      />
      <select onChange={(e) => setSelectedQuadrant(Number(e.target.value))}>
        <option value={1}>Important & Urgent</option>
        <option value={2}>Important & Not Urgent</option>
        <option value={3}>Not Important & Urgent</option>
        <option value={4}>Not Important & Not Urgent</option>
      </select>
      <button onClick={addTask}>Add Task</button>

      <div className="matrix">
        {[1, 2, 3, 4].map((quadrant) => (
          <TaskList
            key={quadrant}
            quadrant={quadrant}
            tasks={tasks.filter(t => t.quadrant === quadrant)}
            deleteTask={deleteTask}
            toggleTaskCompletion={toggleTaskCompletion}
            startTimer={startTimer}
            stopTimer={stopTimer}
          />
        ))}
      </div>

      <Line data={chartData} />
    </div>
  );
}

export default App;
